const INDICATORS = [{"id":"atr","file":"atr.svg","category":"volatility","name":{"en":"ATR (Average True Range)","hi":"ATR (एवरेज ट्रू रेंज)"},"what":{"en":"The average size of daily price ranges, including gaps. It measures volatility in rupees, not direction.","hi":"अंतराल (gaps) सहित दैनिक कीमत रेंज का औसत आकार। यह दिशा नहीं, अस्थिरता को रुपयों में मापता है।"},"settings":{"en":"14 periods.","hi":"14 अवधि।"},"when":{"en":"To set stop-loss distances and position sizes that fit how much the stock normally moves. Use it for every trade.","hi":"स्टॉप-लॉस की दूरी और पोज़िशन साइज़ तय करने के लिए, जो शेयर की सामान्य चाल के अनुरूप हों। हर ट्रेड के लिए उपयोगी।"},"how":{"en":"Stop distance = 2 × ATR below the entry (for a long trade). Position size = maximum loss ÷ (2 × ATR). Example: entry ₹250, ATR ₹4, stop ₹242 (2 × ATR = ₹8 below). With ₹1,000 maximum loss, size = 1,000 ÷ 8 = 125 shares. Targets of 2 to 3 × ATR keep the reward in proportion.","hi":"स्टॉप की दूरी = एंट्री से नीचे 2 × ATR (लॉन्ग ट्रेड के लिए)। पोज़िशन साइज़ = अधिकतम नुकसान ÷ (2 × ATR)। उदाहरण: एंट्री ₹250, ATR ₹4, स्टॉप ₹242 (2 × ATR = ₹8 नीचे)। ₹1,000 अधिकतम नुकसान पर साइज़ = 1,000 ÷ 8 = 125 शेयर। 2 से 3 × ATR का टारगेट इनाम को अनुपात में रखता है।"},"mistake":{"en":"Using a fixed stop in rupees on every stock. A volatile stock needs a wider stop, or normal noise will stop you out.","hi":"हर शेयर पर रुपयों में एक तय स्टॉप लगाना। ज़्यादा अस्थिर शेयर को चौड़ा स्टॉप चाहिए, वरना सामान्य उतार-चढ़ाव आपको बाहर कर देगा।"},"pairs":{"en":"Any entry signal above, for the stop and size.","hi":"ऊपर का कोई भी एंट्री संकेत, स्टॉप और साइज़ के लिए।"}},{"id":"adx","file":"adx.svg","category":"trend","name":{"en":"ADX (trend strength)","hi":"ADX (ट्रेंड की ताकत)"},"what":{"en":"Measures how strong a trend is, on a 0 to 100 scale. It does not show direction. The +DI and -DI lines show which side is stronger.","hi":"0 से 100 के पैमाने पर ट्रेंड कितना मज़बूत है, यह मापता है। यह दिशा नहीं दिखाता। +DI और -DI रेखाएँ बताती हैं कि कौन सी ओर ज़्यादा मज़बूत है।"},"settings":{"en":"14 periods. Levels: 20 (weak or range), 25 (trend).","hi":"14 अवधि। स्तर: 20 (कमज़ोर या रेंज), 25 (ट्रेंड)।"},"when":{"en":"To choose your toolkit: trend tools when ADX is above 25 and rising, range tools when it is below 20.","hi":"अपना टूलकिट चुनने के लिए: ADX 25 से ऊपर और बढ़ रहा हो तो ट्रेंड टूल, 20 से नीचे हो तो रेंज टूल।"},"how":{"en":"ADX above 25 and rising with +DI above -DI: use moving-average pullbacks or breakouts (long side). ADX below 20: avoid trend-following entries and use RSI or Bollinger reversals near the range edges. A falling ADX from a high level often means the trend is tiring.","hi":"ADX 25 से ऊपर और बढ़ रहा हो, और +DI, -DI से ऊपर हो: मूविंग एवरेज पुलबैक या ब्रेकआउट (लॉन्ग साइड) इस्तेमाल करें। ADX 20 से नीचे: ट्रेंड-फ़ॉलोइंग एंट्री से बचें, रेंज के किनारों पर RSI या बोलिंगर रिवर्सल इस्तेमाल करें। ऊँचे स्तर से गिरता ADX अक्सर बताता है कि ट्रेंड थक रहा है।"},"mistake":{"en":"Reading ADX as a buy or sell signal. It only tells you how strong a trend is.","hi":"ADX को ख़रीद या बिक्री संकेत समझना। यह केवल बताता है कि ट्रेंड कितना मज़बूत है।"},"pairs":{"en":"Moving averages or breakouts (for direction) and ATR (for stops).","hi":"मूविंग एवरेज या ब्रेकआउट (दिशा के लिए) और ATR (स्टॉप के लिए)।"}}];
const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Volatility","hi":"अस्थिरता (वोलैटिलिटी)"},"def":{"en":"How much and how quickly a price moves. Higher volatility means bigger swings in both directions.","hi":"कीमत कितनी और कितनी तेज़ी से बदलती है। ज़्यादा अस्थिरता का मतलब दोनों दिशाओं में बड़े उतार-चढ़ाव।"}},{"cat":"basics","term":{"en":"Diversification","hi":"विविधीकरण"},"def":{"en":"Spreading money across different investments to reduce the damage from any one of them.","hi":"किसी एक निवेश के नुकसान का असर घटाने के लिए पैसा अलग-अलग निवेशों में बाँटना।"}},{"cat":"technical","term":{"en":"Risk-reward ratio","hi":"जोखिम-इनाम अनुपात"},"def":{"en":"The potential profit of a trade compared with its potential loss. A 1:2 ratio means ₹2 of reward for each ₹1 risked.","hi":"किसी ट्रेड के संभावित लाभ की उसके संभावित नुकसान से तुलना। 1:2 का मतलब हर ₹1 जोखिम पर ₹2 इनाम।"}},{"cat":"trading","term":{"en":"Position sizing","hi":"पोज़िशन साइज़िंग"},"def":{"en":"Deciding how many shares to buy based on the maximum loss you accept and the distance to your stop.","hi":"आपके स्वीकार्य अधिकतम नुकसान और स्टॉप की दूरी के आधार पर तय करना कि कितने शेयर ख़रीदें।"}},{"cat":"trading","term":{"en":"Drawdown","hi":"ड्रॉडाउन"},"def":{"en":"The fall from a peak to a later low in your account or in a price, shown as a percentage.","hi":"खाते या कीमत में एक शिखर से बाद के निचले स्तर तक की गिरावट, प्रतिशत में।"}},{"cat":"trading","term":{"en":"Leverage","hi":"लीवरेज"},"def":{"en":"Using borrowed money or margin to take a bigger position. It magnifies both gains and losses.","hi":"बड़ी पोज़िशन लेने के लिए उधार या मार्जिन का उपयोग। यह लाभ और नुकसान दोनों बढ़ाता है।"}}];
window.MP_PRACTICE = {"risk-management":[["calc:position-size","With ₹10 lakh capital and 1% risk, calculate the position size for an entry at ₹500 with a stop at ₹480.","₹10 लाख पूँजी और 1% जोखिम के साथ ₹500 पर एंट्री और ₹480 पर स्टॉप के लिए पोज़िशन साइज़ निकालें।"],["chart","Place that trade in the terminal and draw a long risk-reward box on the chart with a 1:2 target.","वह ट्रेड टर्मिनल में लगाएँ और चार्ट पर 1:2 टारगेट के साथ लॉन्ग रिस्क-रिवॉर्ड बॉक्स बनाएँ।"],["journal","After ten closed trades, open Diagnostics and read your expectancy, average R and maximum drawdown.","दस बंद ट्रेड के बाद डायग्नॉस्टिक्स खोलें और अपनी एक्सपेक्टेंसी, औसत R और अधिकतम ड्रॉडाउन पढ़ें।"]]};
